/* @lc app=leetcode id=934 lang=kotlin */ class Solution { fun nb(g: Array<IntArray>, p: IntArray) = listOf(intArrayOf(1, 0), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(0, -1)).map { intArrayOf(p[0] + it[0], p[1] + it[1]) }.filter { it[0] in g.indices && it[1] in g.indices } fun set(g: Array<IntArray>, p: IntArray, v: Int) { g[p[0]][p[1]] = v } fun shortestBridge(grid: Array<IntArray>): Int = (0 until grid.size * grid.size).first { grid[it / grid.size][it % grid.size] == 1 }.let { s -> intArrayOf(s / grid.size, s % grid.size).let { st -> java.util.ArrayDeque(listOf(st)).also { set(grid, st, 2) } } }.let { q -> generateSequence { q.poll() }.onEach { p -> nb(grid, p).filter { grid[it[0]][it[1]] == 1 }.forEach { x -> set(grid, x, 2).also { q.add(x) } } }.toList() }.let { isl -> generateSequence(isl) { f -> f.flatMap { nb(grid, it) }.filter { grid[it[0]][it[1]] == 0 }.distinctBy { it[0] * grid.size + it[1] }.onEach { set(grid, it, 2) }.takeIf { it.isNotEmpty() } }.indexOfFirst { f -> f.any { p -> nb(grid, p).any { grid[it[0]][it[1]] == 1 } } } } }